// 取 text
const text = $('Edit-Images-ResultFieldsStart').first().json.query;

// 初始化
const messages = [
  {
    type: 'text',
    text,
  },
];

const images = [];

// 遍历输入 items
for (const item of $input.all()) {
  const { success, pulic_api, filename } = item.json;

  if (success === true && pulic_api && filename) {
    const url = `${pulic_api}${filename}`;

    messages.push({
      type: 'image_url',
      image_url: { url },
    });

    images.push(url);
  }
}

// 输出
return [
  {
    json: {
      messages,
      images,
    },
  },
];

// 假设 LLM 输出在 items[0].json.text 或 items[0].json.content，可以根据实际情况调整
const raw = items[0].json.text || items[0].json.content || items[0].json.output || JSON.stringify(items[0].json);

const start = raw.indexOf('{');
const end = raw.lastIndexOf('}');
if (start === -1 || end === -1 || end <= start) {
  throw new Error('未找到合法JSON');
}

const jsonStr = raw.substring(start, end + 1);
let jsonData;
try {
  jsonData = JSON.parse(jsonStr);
} catch (e) {
  throw new Error('JSON 解析失败: ' + e.message);
}

return [{json: jsonData}];

