function parseFileSize(sizeStr) {
    if (!sizeStr) return 0;
    if (typeof sizeStr === 'number') return sizeStr;
    const match = sizeStr.match(/^([\d.]+)\s*(b|kb|mb|gb)?$/i);
    if (!match) return Number(sizeStr) || 0;
    let [_, numStr, unit] = match;
    let num = parseFloat(numStr);
    if (!unit) return num;
    switch (unit.toLowerCase()) {
        case 'kb': return num * 1024;
        case 'mb': return num * 1024 * 1024;
        case 'gb': return num * 1024 * 1024 * 1024;
        default: return num;
    }
}

const allowedMimeTypes = ['image/png', 'image/jpeg', 'image/webp', 'application/octet-stream'];
const allowedExtensions = ['png', 'jpg', 'jpeg', 'webp'];
const maxSize = 500 * 1024;

const items = $input.all();

const filtered = items.filter(item => {
    const binary = item.binary?.data;
    if (!binary) return false;

    const isMimeAllowed = allowedMimeTypes.includes(binary.mimeType);
    const isExtAllowed = allowedExtensions.includes(
        String(binary.fileExtension || '').toLowerCase()
    );

    let size = parseFileSize(binary.fileSize) || 0;
    // 补充base64长度兜底
    if (!size && binary.data) {
        size = Math.ceil((binary.data.length * 3) / 4);
    }

    return (isMimeAllowed || isExtAllowed) && size <= maxSize;
});

return filtered;
